import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring } from '../remotionShim';


export type SiriOverlayProps = Record<string, any>;

// Helper for smooth, deterministic fluid oscillations
const getOscillation = (
  frame: number,
  fps: number,
  freq: number,
  amp: number,
  phase = 0,
  speed = 1
) => {
  return Math.sin((frame / fps) * 2 * Math.PI * (freq * speed) + phase) * amp;
};

